module tb_csr;

  bit done_a, done_b;

  tb_csr_leg #(
      .PROBE_W    (32),
      .DEPTH_LOG2 (8),
      .RLE_EN     (1'b0),
      .TRIG_SAMPLE(128),
      .N_STIM     (640),
      .VEC_PREFIX ("sim/build/vectors/cap_w32_d8"),
      .NAME       ("w32_d8")
  ) leg_a (
      .done(done_a)
  );

  tb_csr_leg #(
      .PROBE_W    (512),
      .DEPTH_LOG2 (10),
      .RLE_EN     (1'b1),
      .TRIG_SAMPLE(512),
      .N_STIM     (2560),
      .VEC_PREFIX ("sim/build/vectors/cap_w512_d10"),
      .NAME       ("w512_d10")
  ) leg_b (
      .done(done_b)
  );

  initial begin
    wait (done_a && done_b);
    $display("TB_RESULT: PASS");
    $finish;
  end

  initial begin
    #50ms;
    $display("TB_RESULT: FAIL");
    $fatal(1, "timeout: done=%b%b", done_a, done_b);
  end

endmodule
